    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type !== 'connected' && frame.type !== 'pong') {
        frames.push(frame);
        return;
      }
      if (frame.type === 'pong') return resolve();
      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {connected, frames};
};

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});
import type {SessionEntry} from './session.js';
import type {SessionCursor, SessionSummary} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame extends Omit<SessionSummary, 'createdAt' | 'updatedAt'> {
  createdAt: string;
  updatedAt: string;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage;

export {ErrorCodes} from './session.js';
import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}
CHANGELOG.md:13:- `SessionStore.listFor(userId, options?)`, an optional store member that answers the summaries of a user's conversations — `sessionId`, `createdAt`, `updatedAt` and `entryCount` — most recent activity first, so a consumer can build a conversation list instead of only rejoining one. The WebSocket transport answers `list_sessions` with a `session_list` for the authenticated user. `InMemorySessionStore` and `MongoSessionStore` both implement it; a store of your own may leave it out. A summary never carries a conversation's entries or its credentials. Page with `limit` (50 by default, 200 at most, and `0` answers nothing) and `before`, which takes the last summary you saw: the cursor carries both `updatedAt` and `sessionId`, so two conversations saved in the same millisecond cannot straddle a page boundary and go unlisted. See `docs/session-stores.md` § Listing a user's conversations.
CHANGELOG.md:19:- The index to create for `MongoSessionStore` is now `{userId: 1, updatedAt: -1, _id: -1}`. The two-key form that served `latestFor` cannot satisfy `listFor`'s sort, so Mongo would sort a user's whole history on every page. `docs/session-stores.md` § Latest session has the command.
CHANGELOG.md:42:- Stored assistant and thinking entries gain an optional `suppressed: true` when a tool suppressed the response and the client was shown the entry blank or not at all. A resumed session replays such an entry as `entry_skip`, so a reconnecting client never sees text a tool hid. The entry keeps its text for the model's history.
