async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined,
  options: MessageHandlerOptions = {}
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message, options);
  if (message.type === 'list_conversations') await handleListConversations(ws, session, sessionStore, message, options);
}

async function handleListConversations(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListConversationsMessage,
  options: MessageHandlerOptions
): Promise<void> {
  if (!options.history?.enabled || !sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation listing is not supported');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });
    sendJson(ws, {type: 'conversation_list', conversations: summaries.map(toSessionSummaryFrame)});
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation listing is not supported');
      return;
    }
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list conversations', {sessionId: session.sessionId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage,
  options: MessageHandlerOptions = {}
): Promise<void> {
  if (options.history?.enabled === false) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation listing is not supported');
    return;
  }
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSessionSummaryFrame)});
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function toSessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  return validator === undefined ? {valid: false, error: `Unknown message type: ${message.type}`} : validator(message);
}

const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
  list_conversations: validateListConversationsMessage,
};

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (limit !== undefined && (!Number.isInteger(limit) || (limit as number) < 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (message.before === undefined) {
    return {valid: true, data: {type: 'list_sessions', limit: limit as number | undefined}};
  }

  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const before = message.before as Record<string, unknown>;
  if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }

  if (!isValidTimestamp(before.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: limit as number | undefined,
      before: {sessionId: before.sessionId, updatedAt: before.updatedAt as string | number},
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (limit !== undefined && (!Number.isInteger(limit) || (limit as number) < 1 || (limit as number) > 200)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (message.before === undefined)
    return {valid: true, data: {type: 'list_conversations', limit: limit as number | undefined}};
  if (typeof message.before !== 'object' || message.before === null) {
    return {valid: false, error: 'list_conversations before must be an object'};
  }

  const before = message.before as Record<string, unknown>;
  if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
    return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
  }
  if (typeof before.updatedAt !== 'string' || Number.isNaN(Date.parse(before.updatedAt))) {
    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date'};
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      limit: limit as number | undefined,
      before: {sessionId: before.sessionId, updatedAt: before.updatedAt},
    },
  };
}

function isValidTimestamp(value: unknown): value is string | number {
  if (typeof value === 'number') return Number.isFinite(value) && Number.isFinite(new Date(value).getTime());
  return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}
